    if (path.startsWith("/") && path.length() > 1) {
        path = path.substring(1);
    }
    String[] segments = path.split("/");
    for (String segment : segments) {
        if (segment.isEmpty()) {
            continue; // skip empty segments that may arise from leading/trailing '/'
